  const source = clean(text);
  const confirmed = first(source, [/laufender\s+betrieb/i, /gesch[aä]fts[uü]bernahme/i, /nachfolger\s+gesucht/i, /bestehendes\s+caf[eé]/i, /gegen\s+abl[oö]se\s+zu\s+[uü]bernehmen/i]);
